rollback.sql:
DO $garde$
DECLARE
    annules INTEGER; par_role INTEGER; reaffectes INTEGER; historique INTEGER;
BEGIN
    SELECT count(*) INTO annules FROM ${database.defaultSchemaName}.circuit WHERE statut = 'ANNULE';
    SELECT count(*) INTO par_role FROM ${database.defaultSchemaName}.circuit_validateur WHERE employe_id IS NULL;
    SELECT count(*) INTO reaffectes FROM ${database.defaultSchemaName}.circuit_validateur WHERE reaffecte_le IS NOT NULL;
    -- Tout ce qui dépasse « une dernière décision par validateur » : décisions
    -- antérieures (caduques, retirées) et décisions de retrait.
    SELECT count(*) INTO historique FROM (
        SELECT d.id, row_number() OVER (PARTITION BY d.circuit_validateur_id ORDER BY d.cree_le DESC, d.id DESC) AS rang,
               d.decision
          FROM ${database.defaultSchemaName}.decision d) x
     WHERE x.rang > 1 OR x.decision = 'ANNULEE';
    IF (annules + par_role + reaffectes + historique) > 0
       AND coalesce(current_setting('ged.retour_arriere_avec_perte', true), '') <> 'oui' THEN
        RAISE EXCEPTION 'Retour arrière de la reprise des signatures refusé : il perdrait % circuit(s) annulé(s), % validateur(s) par rôle, % réaffectation(s) et % décision(s) d''historique, que l''ancien modèle ne sait pas représenter. Décision explicite requise : ged.retour_arriere_avec_perte = oui (DEPLOIEMENT.md §8).',
            annules, par_role, reaffectes, historique;
    END IF;
END
$garde$
